 $this->$property;		}    }    public function __set($property, $value) {        if (property_exists($this, $property)) {            $this->$property = $value;        }    }		public function __toString(){        return "Phụng Vụ::FILE<br>".$this->viewFile();    }}?><?phpclass phungvu extends PV{	public $tc;	public $tvdc;	public function __construct($path){		parent::__construct($path);    }		public function thanhca($path){		$this->tc = new TC($path);		$this->tc->baihat = $this->tc->json;	}		public function nam($letter, $path){		if(isset($this->json[$letter])){			//return $this->json[$letter];			$nam = $this->json[$letter];			$this->tvdc = new TVDC("$path$letter.json");			$this->tvdc->json['start'] = $nam['start'];			$this->tvdc->json['end'] = $nam['end'];						$this->tvdc->baihat = $this->tvdc->json;		}	}}?><?phpclass TC extends PV{	public $baihat;	public function __construct($path){		parent::__construct($path);    }		public function printList($mobile){		$mess = '';		$slash = '/';		$path = $this->baihat["path"].$slash;		$subpath = $this->baihat["sub"];		if($subpath!='')	$subpath .= $slash;		foreach($this->baihat['list'] as $s){			$pdf = $path.$subpath.$s['dir'].$slash.$s['pdf'].'.pdf';			$tg = '<span class="tacgia"></span>';			if($mobile){				$tg = '<span class="tacgia">tg:&nbsp;&nbsp;&nbsp;&nbsp;</span>';			}					$mess .= '<div id="row">';			$mess .= '<div class="col-md-6"><a href="'.$this->serURL.$pdf.'" title="'.$this->serURL.$pdf.'"><img src="images/pdf_icon.gif" width="12"/></a>';			if($this->in_range($this->today, $s['date'], $s['date'])){				$mess .= '&nbsp;&nbsp;&nbsp;<img src="images/new10_e0.gif" style="" width="16"/>';			}			if(0 === strpos($s['pdf'], 'BaiThuongKho')){				$mess .= '&nbsp;&nbsp;&nbsp;<a href="'.$this->serURL.$pdf.'" title="'.$this->serURL.$pdf.'">'.$s['name'].'</a></div>';			}else{				$mess .= '&nbsp;&nbsp;&nbsp;<a class="tvdc" href="'.$path.$subpath.$s['dir'].$slash.'" title="'.$s['dir'].'">'.$s['name'].'</a></div>';			}			if($s["caudau"]=="&nbsp;"){								$mess .= '<div class="col-md-6">'.$tg.'<span class="tgName">'.$s["tacgia"].'<span></div>';			}else{				$mess .= '<div class="col-md-2">'.$tg.'<span class="tgName">'.$s["tacgia"].'<span></div>';				$mess .= '<div class="col-md-4 italic">'.$s["caudau"].'</div><div class="clearfix visible-sm-block visible-md-block visible-lg-block"></div>';							}			$mess .= '</div>';		}		return $mess;	}}?><?phpclass CNL extends PV{	public $baihat;	public $mobile;	public function __construct($path){		parent::__construct($path);		$this->baihat = $this->json;    }		public function isLeExisted($le){		return isset($this->baihat[$le]);	}		public function printCNL($le){		$mess = '';		$slash = '/';		$cnl = $this->baihat[$le];		//$path = $cnl["path"].$slash;		$folder = $this->baihat["path"].$slash.$cnl['dir'].$slash;		$plcnl = '<span class="plcnl"></span>';		if($this->mobile){			$plcnl = '<span class="plcnl">'.$cnl["title"].':&nbsp;&nbsp;</span>';		}		$mess .= $plcnl.'<a class="tvdc" href="'.$folder.'" title="'.$folder.'"><span class="cnl_tvdc" id="">'.$cnl["name"].'</span></a>';				return $mess;	}}?><?phpclass TVDC extends PV{	public $baihat;	public $cnl;	public function __construct($path){		parent::__construct($path);		$jsonDIR = substr($path, 0, strrpos($path, '/'));		$this->cnl = new CNL($jsonDIR."/cnl.json");    }		public function printList($mobile){		if($mobile){			$this->cnl->mobile = $mobile;		}		$mess = '';		$slash = '/';		$path = $this->baihat["path"].$slash;		$done = false; $miss = false;				foreach($this->baihat['list'] as $s){			$cnl = '';			if($this->cnl->isLeExisted($s['le'])){				$cnl = $this->cnl->printCNL($s['le']);			}						$tv = $s['tv'];			if (is_numeric($tv)){				$tv = $this->baihat["type"].' '.$s['tv'];			}			$folder = $path.$s['dir'].$slash;			if(!is_dir("../taphat/$folder")){				$miss = true;			}else{				$miss = false;			}						$dateClss = "d";			$flashingID_1 = $flashingID_2 = "";			if(!$done && $this->in_range($this->lastSundayDate, $this->nextSundayDate, $s['date'])){				$dateClss = "r";				$flashingID_1 = 'id="flashingtext1"';								if(!empty($cnl)){					$emptyID = 'id=""';					$flashingID_2 = 'id="flashingtext2"';										$cnl = str_replace($emptyID,$flashingID_2,$cnl);				}				$done = true;			}						$pldc = '<span class="pldc"></span>';			$cls = '';			if($miss)	$cls = 'style="color: silver;"';			if($mobile){				$pldc = '<span class="pldc">ĐC:&nbsp;&nbsp;&nbsp;&nbsp;</span>';				$cls = 'style="margin-bottom: 15px;"';			}			$mess .= '<div id="row" '.$cls.'>';			$mess .= '<div class="col-sm-1 col-md-1"><span class="'.$dateClss.'">'.$s['date'].'</span></div>';			$mess .= '<div class="col-sm-5 col-md-5"><span class="le_tvdc">'.$s['le'].'</span></div>';			$mess .= '<div class="col-sm-3 col-md-3">'.$pldc;			if($miss){				$mess .= '<span class="tv_tvdc">'.$tv.'</span>';			}else{				$mess .= '<a class="tvdc" href="'.$folder.'" title="'.$folder.'"><span class="tv_tvdc" '.$flashingID_1.'>'.$tv.'</span></a>';			}						if(isset($s["baikhac"])){				foreach($s["baikhac"] as $bk){				    $p = $path;				    if (str_starts_with($bk['dir'], 'baihatmoi')) $p = preg_replace('thanhvinh', '', $path);					$mess .= '<br><a class="tvdc" href="'.$p.$bk['dir'].$slash.'" title="'.$bk['dir'].'"><span class="tv_tvdc" >'.$bk["name"].'</span></a>';				}			}			$mess .= '</div>';						$mess .= '<div class="col-sm-3 col-md-3">'.$cnl.'</div><div class="clearfix visible-sm-block visible-md-block visible-lg-block"></div>';			$mess .= '</div>';		}			return $mess;	}}?>